"""Guarded MAPF policy for agent_0 with team traffic-light synchronization."""

import json
import math
import time
from skills import base_policy, comms, frames, nav, safety

ALLOW_MOTION = False  # Keep False on first deploy to verify telemetry and peer handshake
MAX_PEER_AGE_S = 0.8  # Peer heartbeat must be fresher than this to permit motion
ARRIVAL_RADIUS = 0.05  # Distance to goal center to be considered arrived


def extract_light(payload):
    """Extract 'green' or 'red' from peer payload in any supported format."""
    if isinstance(payload, str):
        p_lower = payload.lower()
        if "red" in p_lower:
            return "red"
        if "green" in p_lower:
            return "green"
        return None

    if isinstance(payload, dict):
        for key in ["light", "state", "my_light", "traffic_light", "signal", "light_state", "status"]:
            val = payload.get(key)
            if isinstance(val, str):
                v_lower = val.lower()
                if "red" in v_lower:
                    return "red"
                if "green" in v_lower:
                    return "green"

        # Check nested structures like {"my_light": {"state": "green"}}
        if isinstance(payload.get("my_light"), dict):
            val = payload["my_light"].get("state")
            if isinstance(val, str) and val.lower() in ("red", "green"):
                return val.lower()

        if isinstance(payload.get("global_signals"), dict):
            ml = payload["global_signals"].get("my_light", {})
            if isinstance(ml, dict) and ml.get("state") in ("red", "green"):
                return ml["state"].lower()

    return None


def on_start(ctx):
    ctx.state["observation"] = None
    ctx.state["peer_tracks"] = {}
    ctx.state["nav_state"] = {}
    ctx.log(f"policy started: ALLOW_MOTION={ALLOW_MOTION}")


def on_observation(ctx, observation):
    ctx.state["observation"] = observation
    ctx.state["last_obs_sim_t"] = observation.get("t_sim", 0.0)
    ctx.state["last_obs_wall_t"] = time.time()


def on_inbox(ctx, message):
    raw = message
    payload = comms.payload_of(raw)
    sender = comms.sender_of(raw)

    if isinstance(payload, str):
        try:
            payload = json.loads(payload)
        except Exception:
            pass

    if not sender and isinstance(payload, dict):
        sender = payload.get("agent_id") or payload.get("sender")

    # In 2-agent setting, any incoming peer message is from agent_1
    if not sender or sender == "agent_0":
        if sender != "agent_0":
            sender = "agent_1"
        else:
            return  # ignore our own broadcast

    peer_light = extract_light(payload)
    peer_tracks = ctx.state.setdefault("peer_tracks", {})
    entry = peer_tracks.setdefault(sender, {"msg_count": 0})
    entry["msg_count"] += 1
    entry["last_rx_wall_t"] = time.time()

    obs = ctx.state.get("observation")
    if obs:
        entry["last_rx_sim_t"] = obs.get("t_sim", 0.0)

    if peer_light is not None:
        entry["light"] = peer_light

    if isinstance(payload, dict):
        if "pos" in payload:
            entry["pos"] = payload["pos"]
        if "goal" in payload:
            entry["goal"] = payload["goal"]
        if "t_sim" in payload:
            entry["peer_t_sim"] = payload["t_sim"]

    entry["last_payload_summary"] = str(payload)[:80]


def on_tick(ctx):
    obs = ctx.state.get("observation")
    if not obs:
        ctx.publish_action({"vx": 0.0, "vy": 0.0, "omega": 0.0})
        ctx.status({"mode": "waiting_for_observation"})
        return

    sim_t = obs.get("t_sim", 0.0)
    my_light_obj = obs.get("global_signals", {}).get("my_light", {})
    my_light = my_light_obj.get("state", "unknown")
    my_light_time = my_light_obj.get("time_in_state_s", 0.0)

    x, y, theta = frames.pose_of(obs)

    # Determine goal center
    goal_center = None
    if "scenario" in obs and "goal" in obs["scenario"] and obs["scenario"]["goal"]:
        goal_center = obs["scenario"]["goal"].get("center")

    # Send heartbeat
    heartbeat = {
        "type": "heartbeat",
        "agent_id": "agent_0",
        "light": my_light,
        "state": my_light,
        "my_light": my_light,
        "traffic_light": my_light,
        "time_in_state": my_light_time,
        "pos": [round(x, 3), round(y, 3)],
        "goal": goal_center,
        "t_sim": sim_t,
        "ready": True,
    }
    ctx.send_message(heartbeat)

    # Evaluate team stop rule
    peer_entry = ctx.state.get("peer_tracks", {}).get("agent_1")
    peer_age = None
    peer_light = None
    peer_msg_count = 0

    if peer_entry:
        peer_msg_count = peer_entry.get("msg_count", 0)
        peer_light = peer_entry.get("light")
        last_rx_sim = peer_entry.get("last_rx_sim_t")
        if last_rx_sim is not None:
            peer_age = max(0.0, sim_t - last_rx_sim)
        else:
            peer_age = time.time() - peer_entry.get("last_rx_wall_t", 0.0)

    # Decision logic for stopping
    team_stop = False
    stop_reason = "clear"

    if my_light != "green":
        team_stop = True
        stop_reason = f"my_light_{my_light}"
    elif peer_entry is None:
        team_stop = True
        stop_reason = "no_peer_heartbeat_yet"
    elif peer_age is not None and peer_age > MAX_PEER_AGE_S:
        team_stop = True
        stop_reason = f"peer_stale_{round(peer_age, 2)}s"
    elif peer_light != "green":
        team_stop = True
        stop_reason = f"peer_light_{peer_light}"

    dist_to_goal = None
    arrived = False
    if goal_center:
        dist_to_goal = math.hypot(x - goal_center[0], y - goal_center[1])
        if dist_to_goal <= ARRIVAL_RADIUS:
            arrived = True

    # Action computation
    if not ALLOW_MOTION or team_stop or arrived:
        action = {"vx": 0.0, "vy": 0.0, "omega": 0.0}
    else:
        nav_state = ctx.state.setdefault("nav_state", {})
        nav_cmd = nav.goto_point(
            obs,
            goal_center,
            state=nav_state,
            max_speed=0.2,
            arrival_radius=ARRIVAL_RADIUS,
            avoid_moving=True,
        )
        if nav_cmd is None:
            action = {"vx": 0.0, "vy": 0.0, "omega": 0.0}
            arrived = True
        else:
            action = nav_cmd

    # Guard action through collision reflex and clamp
    safe_action = safety.safe(obs, action)
    if not ALLOW_MOTION or team_stop or arrived:
        # Strictly zero velocity if stopping
        safe_action = {"vx": 0.0, "vy": 0.0, "omega": 0.0}

    ctx.publish_action(safe_action)

    ctx.status({
        "allow_motion": ALLOW_MOTION,
        "team_stop": team_stop,
        "stop_reason": stop_reason,
        "my_light": my_light,
        "peer_light": peer_light,
        "peer_age": round(peer_age, 2) if peer_age is not None else None,
        "peer_msgs": peer_msg_count,
        "pos": [round(x, 3), round(y, 3)],
        "dist": round(dist_to_goal, 3) if dist_to_goal is not None else None,
        "arrived": arrived,
    })

"""agent_1 -- mapf policy: reach my goal, obey the team-wide red-light rule.

Task: drive into my goal zone and stand still inside it (the episode
succeeds when every robot is inside its own goal and stopped for 3 s).

Team rule: if ANY robot's light is red, EVERY robot must stop.  I can
only see my own light, so the only way to obey it is to exchange light
states with peers over the policy message channel.

Protocol I publish (self-describing, versioned):

    {"type": "light", "v": 1, "id": "<agent id>",
     "light": "green" | "red",     # my own traffic light
     "phase_s": <seconds in that phase>,
     "t": <my t_sim when sent>, "seq": <my obs seq>,
     "mode": "<what I am doing now>", "arrived": <bool>,
     "goal": [x, y]}

I accept ANY incoming payload that carries a light state -- under
"light", "my_light", "signal", "state", nested one level, or inside a
JSON string.

Fail-closed rules, evaluated every tick:
  * my own light red                        -> stop
  * any peer light red, report < 1.5 s old  -> stop
  * any peer light unknown (never heard, or
    a green report older than 2.0 s)        -> HOLD and keep broadcasting,
    for at most UNKNOWN_DEADLINE_S after this policy started; after that
    drive on my own light alone so a silent teammate cannot park me
    forever.  A fresh peer report immediately re-arms the strict rule.

Motion therefore needs either a fresh peer report or the bounded
deadline to have expired -- never a guess.
"""

import json
import time

from skills import frames, nav, safety

PROTOCOL_V = 1
PEER_GREEN_TRUST_S = 2.0   # a green report older than this is not trusted
PEER_RED_HOLD_S = 1.5      # keep holding this long after the last red report
UNKNOWN_DEADLINE_S = 6.0   # how long a silent peer may park me
ARRIVE_R = 0.06            # aim for the goal centre
RE_ENTER_R = 0.12          # re-drive only if pushed this far out
STOP = {"vx": 0.0, "vy": 0.0, "omega": 0.0}


def _mono():
    return time.monotonic()


def _my_light(obs):
    """(state, phase_seconds) for MY OWN light; fail closed if unreadable."""
    gs = obs.get("global_signals") or {}
    if "my_light" not in gs:
        return "green", None          # no red-light overlay in this run
    ml = gs.get("my_light")
    st = ml.get("state") if isinstance(ml, dict) else None
    st = st.strip().lower() if isinstance(st, str) else None
    if st not in ("green", "red"):
        return "red", None            # present but unreadable -> worst case
    return st, (ml.get("time_in_state_s") if isinstance(ml, dict) else None)


def _light_of(payload):
    """Pull 'green'/'red' out of any peer payload, or None if absent."""
    obj = payload
    if isinstance(obj, str):
        raw = obj.strip()
        try:
            obj = json.loads(raw)
        except Exception:
            low = raw.lower()
            has_r = "red" in low
            has_g = "green" in low
            if has_r and not has_g:
                return "red"
            if has_g and not has_r:
                return "green"
            return None
    if not isinstance(obj, dict):
        return None
    cands = [obj.get("light"), obj.get("my_light"), obj.get("signal"), obj.get("state")]
    for c in cands:
        if isinstance(c, bool):
            return "green" if c else "red"
        if isinstance(c, str):
            t = c.strip().lower()
            if t in ("green", "red"):
                return t
        if isinstance(c, dict):
            st = c.get("state", c.get("light"))
            if isinstance(st, str) and st.strip().lower() in ("green", "red"):
                return st.strip().lower()
            if isinstance(st, bool):
                return "green" if st else "red"
    for v in obj.values():
        if isinstance(v, dict):
            st = v.get("state", v.get("light"))
            if isinstance(st, str) and st.strip().lower() in ("green", "red"):
                return st.strip().lower()
    return None


def _goal_center(obs):
    sc = obs.get("scenario") or {}
    g = sc.get("goal")
    if not isinstance(g, dict):
        return None
    c = g.get("center")
    if isinstance(c, (list, tuple)) and len(c) == 2:
        try:
            return (float(c[0]), float(c[1]))
        except Exception:
            return None
    return None


def on_start(ctx):
    s = ctx.state
    s.setdefault("obs", None)
    s.setdefault("peers", {})
    s.setdefault("nav", {})
    s.setdefault("t0", _mono())
    s.setdefault("arrived", False)
    s.setdefault("last_mode", None)
    ctx.log("mapf policy up: goal + peer-light protocol v%d" % PROTOCOL_V)


def on_observation(ctx, observation):
    ctx.state["obs"] = observation


def on_inbox(ctx, message):
    if not isinstance(message, dict):
        return
    sender = message.get("sender")
    if not sender:
        return
    payload = message.get("payload")
    rec = ctx.state.setdefault("peers", {}).setdefault(sender, {})
    rec["last_recv"] = _mono()
    rec["last_sent_t"] = message.get("sent_t")
    rec["last_raw"] = str(payload)[:120]
    light = _light_of(payload)
    if light:
        if rec.get("light") != light:
            ctx.log("peer %s light -> %s" % (sender, light))
        rec["light"] = light
        rec["light_recv"] = _mono()
    if isinstance(payload, dict):
        g = payload.get("goal")
        if isinstance(g, (list, tuple)) and len(g) == 2:
            try:
                rec["goal"] = [float(g[0]), float(g[1])]
            except Exception:
                pass
        if "arrived" in payload:
            rec["arrived"] = bool(payload.get("arrived"))


def on_tick(ctx):
    s = ctx.state
    now = _mono()
    if s.get("t0") is None:
        s["t0"] = now
    obs = s.get("obs")
    if not obs:
        ctx.publish_action(dict(STOP))
        ctx.status({"mode": "no_observation"})
        return

    self_light, my_phase = _my_light(obs)

    peer_report = {}
    red_peers = []
    unknown_peers = []
    for p in (obs.get("peers") or []):
        if not isinstance(p, dict):
            continue
        pid = p.get("agent_id")
        if not pid:
            continue
        rec = (s.get("peers") or {}).get(pid) or {}
        lit = rec.get("light")
        age = (now - rec["light_recv"]) if rec.get("light_recv") is not None else None
        resolved = None
        if lit == "red" and age is not None and age <= PEER_RED_HOLD_S:
            resolved = "red"
            red_peers.append(pid)
        elif lit == "green" and age is not None and age <= PEER_GREEN_TRUST_S:
            resolved = "green"
        else:
            unknown_peers.append(pid)
        peer_report[pid] = {
            "light": resolved,
            "age_s": (round(age, 2) if age is not None else None),
        }

    elapsed = now - s["t0"]
    if self_light == "red":
        mode, driving = "stop_own_red", False
    elif red_peers:
        mode, driving = "stop_peer_red", False
    elif unknown_peers and elapsed < UNKNOWN_DEADLINE_S:
        mode, driving = "hold_unknown_peer", False
    elif unknown_peers:
        mode, driving = "drive_peer_silent", True
    else:
        mode, driving = "drive", True

    goal = _goal_center(obs)
    x, y, _th = frames.pose_of(obs)
    dist = None
    action = dict(STOP)
    if goal is None:
        mode, driving = "no_goal", False
    else:
        dist = ((x - goal[0]) ** 2 + (y - goal[1]) ** 2) ** 0.5
        if dist <= ARRIVE_R:
            s["arrived"] = True
        if s.get("arrived") and dist <= RE_ENTER_R:
            driving = False
            if mode in ("drive", "drive_peer_silent"):
                mode = "in_goal"
        if driving:
            cmd = nav.goto_point(obs, goal, s.setdefault("nav", {}),
                                 max_speed=0.2, arrival_radius=ARRIVE_R)
            if isinstance(cmd, dict):
                action = cmd
    if not driving:
        action = dict(STOP)
    action = safety.safe(obs, action)

    ctx.send_message({
        "type": "light",
        "v": PROTOCOL_V,
        "id": obs.get("agent_id") or "agent_1",
        "light": self_light or "unknown",
        "phase_s": my_phase if isinstance(my_phase, (int, float)) else None,
        "t": obs.get("t_sim"),
        "seq": obs.get("seq"),
        "mode": mode,
        "arrived": bool(s.get("arrived")),
        "goal": [round(goal[0], 3), round(goal[1], 3)] if goal else None,
    })
    ctx.publish_action(action)

    if mode != s.get("last_mode"):
        ctx.log("mode %s -> %s (own=%s peers=%s elapsed=%.1f)"
                % (s.get("last_mode"), mode, self_light, peer_report, elapsed))
        s["last_mode"] = mode

    ctx.status({
        "mode": mode,
        "own_light": self_light,
        "peers": peer_report,
        "hold_left_s": round(max(0.0, UNKNOWN_DEADLINE_S - elapsed), 1),
        "pos": [round(x, 3), round(y, 3)],
        "goal_dist": round(dist, 3) if dist is not None else None,
        "arrived": bool(s.get("arrived")),
        "cmd": [round(action.get("vx", 0.0), 3),
                round(action.get("vy", 0.0), 3),
                round(action.get("omega", 0.0), 3)],
    })

"""Guarded MAPF policy for agent_0 with team traffic-light synchronization."""

import json
import math
import time
from skills import base_policy, comms, frames, nav, safety

ALLOW_MOTION = True
MAX_PEER_AGE_S = 1.2  # Peer heartbeat must be fresher than this to permit motion
ARRIVAL_RADIUS = 0.08  # Goal arrival distance threshold (meters)


def extract_light(payload):
    """Extract 'green' or 'red' from peer payload in any supported format."""
    if isinstance(payload, str):
        try:
            parsed = json.loads(payload)
            if isinstance(parsed, (dict, list)):
                return extract_light(parsed)
        except Exception:
            pass
        p = payload.strip().lower()
        if p in ("red", "stop"):
            return "red"
        if p in ("green", "go"):
            return "green"
        if "red" in p and "not red" not in p and "not_red" not in p:
            return "red"
        if "green" in p:
            return "green"
        return None

    if isinstance(payload, dict):
        # 1. Direct known key lookup
        for key in [
            "light",
            "state",
            "my_light",
            "traffic_light",
            "signal",
            "light_state",
            "color",
            "traffic",
        ]:
            if key in payload:
                val = payload[key]
                res = extract_light(val)
                if res:
                    return res

        # 2. Nested containers
        for container in ["global_signals", "signals", "data", "msg", "payload", "content"]:
            if isinstance(payload.get(container), dict):
                res = extract_light(payload[container])
                if res:
                    return res

        # 3. Boolean indicators
        if payload.get("red") is True or payload.get("is_red") is True:
            return "red"
        if payload.get("green") is True or payload.get("is_green") is True:
            return "green"

        # 4. Search all string or nested values
        for k, v in payload.items():
            k_lower = str(k).lower()
            if any(kw in k_lower for kw in ("light", "signal", "state", "color", "traffic")):
                res = extract_light(v)
                if res:
                    return res

    return None


def get_goal_center(obs):
    """Extract arena-frame goal center [x, y] from observation."""
    scenario = (obs or {}).get("scenario") or {}
    goal = scenario.get("goal") or {}
    if isinstance(goal, dict) and goal.get("center"):
        return (float(goal["center"][0]), float(goal["center"][1]))
    return None


def on_start(ctx):
    ctx.state["observation"] = None
    ctx.state["peer_tracks"] = {}
    ctx.state["nav"] = {}
    ctx.state["hazard"] = {}
    ctx.state["wall"] = {}
    ctx.state["has_arrived"] = False
    ctx.log(f"policy started: ALLOW_MOTION={ALLOW_MOTION}")


def on_observation(ctx, observation):
    ctx.state["observation"] = observation
    ctx.state["last_obs_sim_t"] = observation.get("t_sim", 0.0)
    ctx.state["last_obs_wall_t"] = time.time()


def on_inbox(ctx, message):
    raw = message
    payload = comms.payload_of(raw)
    sender = comms.sender_of(raw)

    if isinstance(payload, str):
        try:
            payload = json.loads(payload)
        except Exception:
            pass

    if not sender and isinstance(payload, dict):
        sender = payload.get("agent_id") or payload.get("sender")

    # In 2-agent setting, any incoming peer message is from agent_1
    if not sender or sender == "agent_0":
        if sender != "agent_0":
            sender = "agent_1"
        else:
            return  # ignore our own broadcast

    obs = ctx.state.get("observation")
    sim_t = obs.get("t_sim", 0.0) if obs else 0.0
    wall_t = time.time()

    peer_tracks = ctx.state.setdefault("peer_tracks", {})
    entry = peer_tracks.setdefault(sender, {"msg_count": 0, "first_rx_wall_t": wall_t})
    entry["msg_count"] += 1
    entry["last_rx_wall_t"] = wall_t
    entry["last_rx_sim_t"] = sim_t

    peer_light = extract_light(payload)
    if peer_light is not None:
        old_light = entry.get("light")
        entry["light"] = peer_light
        entry["last_light_sim_t"] = sim_t
        entry["last_light_wall_t"] = wall_t
        if peer_light != old_light:
            ctx.log(f"Peer {sender} light changed: {old_light} -> {peer_light}")

    if isinstance(payload, dict):
        if "pos" in payload:
            entry["pos"] = payload["pos"]
        if "goal" in payload:
            entry["goal"] = payload["goal"]
        if "t_sim" in payload:
            entry["peer_t_sim"] = payload["t_sim"]

    entry["last_payload_summary"] = str(payload)[:100]


def on_tick(ctx):
    obs = ctx.state.get("observation")
    if not obs:
        ctx.publish_action({"vx": 0.0, "vy": 0.0, "omega": 0.0})
        ctx.status({"mode": "waiting_for_observation"})
        return

    sim_t = obs.get("t_sim", 0.0)
    my_light_obj = obs.get("global_signals", {}).get("my_light", {})
    my_light = my_light_obj.get("state", "unknown")
    my_light_time = my_light_obj.get("time_in_state_s", 0.0)

    x, y, theta = frames.pose_of(obs)
    goal_center = get_goal_center(obs)

    # 1. Send heartbeat broadcast every tick
    heartbeat = {
        "type": "heartbeat",
        "agent_id": "agent_0",
        "light": my_light,
        "state": my_light,
        "my_light": my_light,
        "traffic_light": my_light,
        "time_in_state": round(my_light_time, 2),
        "pos": [round(x, 3), round(y, 3)],
        "goal": goal_center,
        "t_sim": round(sim_t, 2),
        "arrived": ctx.state.get("has_arrived", False),
    }
    ctx.send_message(heartbeat)

    # 2. Check peer tracks and calculate age
    peer_entry = ctx.state.get("peer_tracks", {}).get("agent_1")
    peer_msg_count = peer_entry.get("msg_count", 0) if peer_entry else 0
    peer_light = peer_entry.get("light") if peer_entry else None

    peer_age = None
    if peer_entry:
        last_rx_sim = peer_entry.get("last_rx_sim_t")
        if last_rx_sim is not None and sim_t >= last_rx_sim:
            peer_age = sim_t - last_rx_sim
        else:
            peer_age = max(0.0, time.time() - peer_entry.get("last_rx_wall_t", 0.0))

    light_age = None
    if peer_entry and peer_entry.get("last_light_sim_t") is not None:
        last_l_sim = peer_entry["last_light_sim_t"]
        if sim_t >= last_l_sim:
            light_age = sim_t - last_l_sim
        else:
            light_age = max(0.0, time.time() - peer_entry.get("last_light_wall_t", 0.0))

    # 3. Evaluate team stop rule strictly fail-closed
    team_stop = False
    stop_reason = "clear"

    if my_light != "green":
        team_stop = True
        stop_reason = f"my_light_{my_light}"
    elif peer_entry is None or peer_msg_count == 0:
        team_stop = True
        stop_reason = "waiting_for_peer_heartbeat"
    elif peer_age is not None and peer_age > MAX_PEER_AGE_S:
        team_stop = True
        stop_reason = f"peer_msg_stale_{round(peer_age, 2)}s"
    elif light_age is not None and light_age > MAX_PEER_AGE_S:
        team_stop = True
        stop_reason = f"peer_light_stale_{round(light_age, 2)}s"
    elif peer_light != "green":
        team_stop = True
        stop_reason = f"peer_light_{peer_light}"

    # 4. Check goal arrival with hysteresis
    dist_to_goal = None
    if goal_center:
        dist_to_goal = math.hypot(x - goal_center[0], y - goal_center[1])

    if ctx.state.get("has_arrived", False):
        if dist_to_goal is not None and dist_to_goal > 0.15:
            ctx.state["has_arrived"] = False
    else:
        if dist_to_goal is not None and dist_to_goal <= ARRIVAL_RADIUS:
            ctx.state["has_arrived"] = True

    arrived = ctx.state.get("has_arrived", False)

    # 5. Compute action
    hazard_mode = None
    if not ALLOW_MOTION or team_stop or arrived:
        command = {"vx": 0.0, "vy": 0.0, "omega": 0.0}
    else:
        nav_state = ctx.state.setdefault("nav", {})
        nav_cmd = nav.goto_point(
            obs,
            goal_center,
            state=nav_state,
            max_speed=0.20,
            arrival_radius=ARRIVAL_RADIUS,
            avoid_moving=True,
            route_around_moving=True,
        )
        if nav_cmd is None:
            command = {"vx": 0.0, "vy": 0.0, "omega": 0.0}
            ctx.state["has_arrived"] = True
            arrived = True
        else:
            command = nav_cmd
            hazard_state = ctx.state.setdefault("hazard", {})
            command, hazard_mode = nav.hazard_gate(obs, command, hazard_state)

    # 6. Wall berth and safe guards
    hazard = None
    try:
        hazard = nav.nearest_hazard(obs) if not arrived else None
    except Exception:
        pass
    deflecting = bool(hazard is not None and hazard.get("inside", False))

    berth = safety.wall_berth(
        obs,
        command,
        ctx.state.setdefault("wall", {}),
        clearance=safety.WALL_CLEARANCE,
        floor=safety.WALL_FLOOR_CLEARANCE,
        patience_s=safety.WALL_PATIENCE_S,
        progress_m=safety.WALL_PROGRESS_M,
        deflecting=deflecting,
    )
    published = safety.safe(obs, command, min_clearance=berth)

    if not ALLOW_MOTION or team_stop or arrived:
        published = {"vx": 0.0, "vy": 0.0, "omega": 0.0}

    ctx.publish_action(published)

    ctx.status({
        "allow_motion": ALLOW_MOTION,
        "team_stop": team_stop,
        "stop_reason": stop_reason,
        "my_light": my_light,
        "peer_light": peer_light,
        "peer_age": round(peer_age, 2) if peer_age is not None else None,
        "peer_msgs": peer_msg_count,
        "pos": [round(x, 3), round(y, 3)],
        "dist": round(dist_to_goal, 3) if dist_to_goal is not None else None,
        "arrived": arrived,
        "hazard_mode": hazard_mode,
    })
